use std::collections::HashMap;
use std::net::{IpAddr, Ipv4Addr, SocketAddr, ToSocketAddrs};
use std::sync::Arc;
use tokio::sync::RwLock;
use reqwest::Url;

#[derive(Clone, Debug, PartialEq)]
enum Role {
    Admin,
    Operator,
    Viewer,
}

#[derive(Clone, Debug)]
struct User {
    username: String,
    role: Role,
    allowed_registries: Vec<String>,
}

#[derive(Clone, Debug)]
struct ContainerSpec {
    image: String,
    registry_url: String,
    health_check_url: Option<String>,
}

struct Orchestrator {
    users: Arc<RwLock<HashMap<String, User>>>,
    containers: Arc<RwLock<Vec<ContainerSpec>>>,
    internal_metadata_prefix: String,
}

impl Orchestrator {
    fn new() -> Self {
        Self {
            users: Arc::new(RwLock::new(HashMap::new())),
            containers: Arc::new(RwLock::new(Vec::new())),
            internal_metadata_prefix: "http://169.254.169.254".to_string(),
        }
    }

    fn is_internal_ip(&self, addr: &IpAddr) -> bool {
        match addr {
            IpAddr::V4(ip) => {
                ip.is_private()
                    || ip.is_loopback()
                    || ip.is_link_local()
                    || ip.is_unspecified()
                    || ip.is_broadcast()
                    // Carrier-grade NAT range 100.64.0.0/10
                    || (ip.octets()[0] == 100 && (ip.octets()[1] & 0xc0) == 64)
            }
            IpAddr::V6(ip) => {
                // If this is an IPv4-mapped address, validate the embedded IPv4.
                if let Some(v4) = ip.to_ipv4() {
                    return self.is_internal_ip(&IpAddr::V4(v4));
                }
                let seg = ip.segments();
                ip.is_loopback()
                    || ip.is_unspecified()
                    // Unique local addresses fc00::/7
                    || (seg[0] & 0xfe00) == 0xfc00
                    // Link-local unicast fe80::/10
                    || (seg[0] & 0xffc0) == 0xfe80
            }
        }
    }

    async fn validate_registry_url(&self, url_str: &str, user: &User) -> Result<Url, String> {
        let url = Url::parse(url_str).map_err(|e| format!("Invalid URL: {}", e))?;

        let host = url.host_str().ok_or("No host in URL")?;

        // Check scheme
        if url.scheme() != "https" && url.scheme() != "http" {
            return Err("Only http/https schemes allowed".to_string());
        }

        // Resolve DNS and check for internal IPs
        let socket_addr = format!("{}:{}", host, url.port_or_known_default().unwrap_or(443));
        let resolved: Vec<SocketAddr> = socket_addr
            .to_socket_addrs()
            .map_err(|e| format!("DNS resolution failed: {}", e))?
            .collect();

        for addr in &resolved {
            if self.is_internal_ip(&addr.ip()) {
                return Err("Internal IPs are not allowed".to_string());
            }
        }

        // Check user's allowed registries
        if user.role != Role::Admin {
            let host_lower = host.to_lowercase();
            if !user.allowed_registries.iter().any(|r| host_lower.ends_with(r)) {
                return Err("Registry not in allowed list".to_string());
            }
        }

        Ok(url)
    }

    async fn validate_health_check_url(&self, url_str: &str, user: &User) -> Result<Url, String> {
        let url = Url::parse(url_str).map_err(|e| format!("Invalid URL: {}", e))?;

        // Health checks: only admins and operators can set custom health check endpoints
        if user.role == Role::Viewer {
            return Err("Viewers cannot set custom health checks".to_string());
        }

        let host = url.host_str().ok_or("No host in URL")?;

        if url.scheme() != "https" && url.scheme() != "http" {
            return Err("Only http/https schemes allowed".to_string());
        }

        // All non-admin roles must pass internal IP check
        // Admins also cannot target internal IPs via health checks
        let port = url.port_or_known_default().unwrap_or(80);
        let socket_addr = format!("{}:{}", host, port);
        let resolved: Vec<SocketAddr> = socket_addr
            .to_socket_addrs()
            .map_err(|e| format!("DNS resolution failed: {}", e))?
            .collect();

        for addr in &resolved {
            if self.is_internal_ip(&addr.ip()) {
                return Err("Health checks cannot target internal IPs".to_string());
            }
        }

        Ok(url)
    }

    async fn deploy_container(&self, spec: ContainerSpec, user: &User) -> Result<String, String> {
        // Validate registry URL
        let _registry = self.validate_registry_url(&spec.registry_url, user).await?;

        // Validate and execute health check if provided
        if let Some(ref hc_url) = spec.health_check_url {
            let validated_url = self.validate_health_check_url(hc_url, user).await?;
            // Perform the health check probe - this makes an actual HTTP request
            let _response = self.probe_endpoint(validated_url).await?;
        }

        let mut containers = self.containers.write().await;
        containers.push(spec.clone());
        Ok(format!("Deployed container with image: {}", spec.image))
    }

    async fn probe_endpoint(&self, url: Url) -> Result<String, String> {
        // Re-resolve at request time and verify IP is still safe (prevent DNS rebinding)
        let host = url.host_str().ok_or("No host")?;
        let port = url.port_or_known_default().unwrap_or(80);
        let socket_addr = format!("{}:{}", host, port);
        let resolved: Vec<SocketAddr> = socket_addr
            .to_socket_addrs()
            .map_err(|e| format!("DNS resolution failed: {}", e))?
            .collect();

        for addr in &resolved {
            if self.is_internal_ip(&addr.ip()) {
                return Err("Resolved to internal IP, aborting probe".to_string());
            }
        }

        let client = reqwest::Client::builder()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(std::time::Duration::from_secs(5))
            .build()
            .map_err(|e| format!("Client error: {}", e))?;

        let resp = client
            .get(url.as_str())
            .send()
            .await
            .map_err(|e| format!("Probe failed: {}", e))?;

        let status = resp.status();
        if !status.is_success() {
            return Err(format!("Health check returned status: {}", status));
        }

        Ok(format!("Health check passed with status: {}", status))
    }

    async fn promote_user_role(&self, target: &str, new_role: Role, requester: &User) -> Result<(), String> {
        if requester.role != Role::Admin {
            return Err("Only admins can change roles".to_string());
        }
        let mut users = self.users.write().await;
        if let Some(user) = users.get_mut(target) {
            user.role = new_role;
            Ok(())
        } else {
            Err("User not found".to_string())
        }
    }
}

#[tokio::main]
async fn main() {
    let orch = Orchestrator::new();
    println!("Container orchestrator initialized");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_viewer_cannot_deploy_health_check() {
        let orch = Orchestrator::new();
        let viewer = User {
            username: "viewer1".to_string(),
            role: Role::Viewer,
            allowed_registries: vec!["docker.io".to_string()],
        };
        let spec = ContainerSpec {
            image: "nginx:latest".to_string(),
            registry_url: "https://registry.docker.io/v2/nginx".to_string(),
            health_check_url: Some("http://169.254.169.254/latest/meta-data".to_string()),
        };
        let result = orch.deploy_container(spec, &viewer).await;
        assert!(result.is_err());
    }
}
